diff:
--- a/src/Insurance/PolicyChecker.cs
+++ b/src/Insurance/PolicyChecker.cs
@@ -14,13 +14,29 @@ public class PolicyChecker
     private readonly IOptions<InsuranceOptions> _options;

     public PolicyChecker(IOptions<InsuranceOptions> options) => _options = options;

-    public Task<PolicyStatus> CheckAsync(string number) =>
-        Task.FromResult(PolicyStatus.Unknown);
+    public async Task<PolicyStatus> CheckAsync(string number, CancellationToken ct)
+    {
+        using var http = new HttpClient
+        {
+            Timeout = TimeSpan.FromSeconds(3),
+        };
+
+        var url = $"{_options.Value.BaseUrl}/policies/{number}";
+        using var response = await http.GetAsync(url, ct);
+
+        if (!response.IsSuccessStatusCode)
+        {
+            return PolicyStatus.Unknown;
+        }
+
+        var body = await response.Content.ReadFromJsonAsync<PolicyDto>(ct);
+        return body?.Active == true ? PolicyStatus.Active : PolicyStatus.Expired;
+    }

     public bool IsSupported(string number) => number.Length == 16;
 }
